for name,query in [('BHRegular','DejaVu Sans'),('BHBold','DejaVu Sans:style=Bold')]:
    font_path=subprocess.check_output(['fc-match','-f','%{file}',query],text=True).strip()
    if 'DejaVuSans' not in font_path: raise RuntimeError('DejaVu Sans font is required')
    pdfmetrics.registerFont(TTFont(name,font_path))
styles=getSampleStyleSheet()
styles.add(ParagraphStyle(name='TitleBH',fontName='BHBold',fontSize=24,leading=29,textColor=colors.HexColor('#15243A'),spaceAfter=14))
styles.add(ParagraphStyle(name='HeadingBH',fontName='BHBold',fontSize=14,leading=18,textColor=colors.HexColor('#1746B0'),spaceBefore=9,spaceAfter=7))
