styles.add(ParagraphStyle(name='SmallBH',fontName='BHRegular',fontSize=8.5,leading=12,textColor=colors.HexColor('#4C6076'),spaceAfter=6))
styles.add(ParagraphStyle(name='TableBH',fontName='BHRegular',fontSize=9,leading=12,textColor=colors.HexColor('#15243A')))
E=html.escape

def para(s,style='BodyBH'): return Paragraph(E(s).replace('\n','<br/>'),styles[style])
def h(s): return ('h',s)
def b(s): return ('b',s)
def lines(n=3): return ('lines',n)
def table(rows,widths=None): return ('table',rows,widths)
def header(c,doc):
    w,hg=doc.pagesize; c.saveState()
    c.setFillColor(colors.HexColor('#1746B0')); c.rect(0,hg-8,w,8,fill=1,stroke=0)
    c.setFont('BHBold',9);c.setFillColor(colors.HexColor('#15243A'));c.drawString(42,hg-32,school)
    c.setFont('BHRegular',8);c.setFillColor(colors.HexColor('#4C6076'));c.drawString(42,hg-46,'Brains Heist IELTS | Lesson 2 | Private teacher-review draft')
    if logo: c.drawImage(ImageReader(str(logo)),w-69,hg-66,27,39,preserveAspectRatio=True,mask='auto')
    c.setStrokeColor(colors.HexColor('#DCE5EF'));c.line(42,37,w-42,37)
    c.setFont('BHRegular',8);c.drawString(42,24,'IELTS-02 v1.0.0 | Classroom materials | No official IELTS result')
    c.drawRightString(w-42,24,str(doc.page));c.restoreState()

def makepdf(rel,title,pages,audience):
    story=[]
    for i,page in enumerate(pages):
        if i:story.append(PageBreak())
        story.append(para(title if i==0 else f'{title} - continued','TitleBH'))
        for obj in page:
            kind=obj[0]
            if kind in ['b','h','small']:story.append(para(obj[1],{'b':'BodyBH','h':'HeadingBH','small':'SmallBH'}[kind]))
            elif kind=='lines':
                for _ in range(obj[1]):
                    t=Table([['']],colWidths=[510],rowHeights=[19]);t.setStyle(TableStyle([('LINEBELOW',(0,0),(-1,-1),.35,colors.HexColor('#DCE5EF'))]));story.append(t)
                story.append(Spacer(1,5))
            elif kind=='table':
                rows=[[para(str(cell),'TableBH') for cell in row] for row in obj[1]]
                t=Table(rows,colWidths=obj[2],repeatRows=1,hAlign='LEFT');t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#EEF3FA')),('VALIGN',(0,0),(-1,-1),'TOP'),('BOX',(0,0),(-1,-1),.5,colors.HexColor('#DCE5EF')),('INNERGRID',(0,0),(-1,-1),.4,colors.HexColor('#DCE5EF')),('LEFTPADDING',(0,0),(-1,-1),7),('RIGHTPADDING',(0,0),(-1,-1),7),('TOPPADDING',(0,0),(-1,-1),8),('BOTTOMPADDING',(0,0),(-1,-1),8)]));story.append(t);story.append(Spacer(1,8))
    dest=out/rel
    SimpleDocTemplate(str(dest),pagesize=(595.276,841.89),leftMargin=42,rightMargin=42,topMargin=81,bottomMargin=51).build(story,onFirstPage=header,onLaterPages=header)
    return {'file':rel,'audience':audience,'pages':len(pages)}

