css='''*{box-sizing:border-box}body{margin:0;background:#F5F7FC;color:#15243A;font:16px/1.6 Arial,sans-serif}main{max-width:980px;margin:auto;padding:24px}h1{font-size:clamp(28px,5vw,48px);line-height:1.15}h2{color:#1746B0}a{color:#1746B0}a:focus-visible,button:focus-visible,select:focus-visible{outline:3px solid #0E7490;outline-offset:3px}button,select{min-height:44px;font:inherit;padding:8px 14px}button{background:#1746B0;color:white;border:0;border-radius:8px}img.logo{width:48px;height:62px;object-fit:contain}li{margin:12px 0}section{background:white;padding:24px;margin:20px 0}small{color:#4C6076}@media print{body{background:white}main{padding:0}button,nav{display:none}section{break-inside:avoid}}'''
start=f'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Lesson 2 start guide</title><style>{css}</style><main><p>{E(school)}<br>Brains Heist IELTS</p><h1>Lesson 2<br>{E(d['title'])}</h1><p><strong>Private teacher-review draft.</strong> Complete the human review record before classroom release. New content is not published in Brains Heist.</p><section><h2>Start here</h2><ol><li>Keep the extracted folder together. Read <a href="Teacher-private/Teacher_Guide.pdf">Teacher Guide</a>.</li><li>Print <a href="Students/Student_Workbook.pdf">Student Workbook</a>, four pages per learner, and <a href="Students/Homework.pdf">Homework</a>.</li><li>Choose <a href="Teacher-private/Lesson_2_Presentation.pptx">editable PowerPoint</a>, <a href="Teacher-private/Lesson_2_Presentation_static.pptx">motion-free PowerPoint</a> or <a href="Teacher-private/Lesson_2_Slides.html">offline HTML slides</a>. Answers reveal only when you advance. Keep teacher files private.</li><li>Use <a href="Teacher-private/Post_Screener_Planning.pdf">Post-screener Planning</a> to check saved evidence and missing reviews before class.</li></ol><p><strong>No recording required.</strong> No Listening Screener, Lesson 1 MP3 or new audio track is needed. The teacher models the strategies live.</p></section><section><h2>When students join later</h2><p>Give them <a href="Students/Late_Joiner_Catchup.pdf">the catch-up sheet</a>. Arrange missing screeners separately with their full time. Keep completed results and join the current class lesson.</p></section><section><h2>Plan B</h2><p>Internet fails: the downloaded lesson works offline. Record online follow-up for later.</p><p>Projector fails: students use the printed passage and model. Read directions from the teacher guide and use the private key.</p><p>Printing fails: show only the student workbook PDF and let students answer in notebooks. Keep the key and fresh follow-up file closed.</p></section><section><h2>After class</h2><p>Keep original work and record support. Choose a supported next action. Assign reviewed online practice through the existing workflow only when appropriate.</p><p>Keep <a href="Teacher-private/Fresh_Transfer_Check.pdf">the fresh follow-up</a> private until its reviewed delivery, about one teaching week later. It is a draft classroom check, not a screener or automatic improvement score.</p><p><a href="Teacher-private/Teacher_Keys_and_Models.pdf">Private teacher keys and models</a></p></section><small>IELTS-02 v1.0.0. Diagnostic Bible 1.10.0; Lessons Bible 1.1.0; Visual &amp; UX Bible 1.1.0. Paper work does not automatically save into IELTS Journey.</small></main></html>'''
