slidecss='''.slide{min-height:72vh;margin:0;padding:32px}.slide[hidden]{display:none}.dark{background:#15243A;color:white}.identity{font-size:14px;color:inherit}.body{font-size:clamp(20px,3vw,32px);line-height:1.4}details{font-size:16px}nav{display:flex;flex-wrap:wrap;gap:12px;padding:16px;background:#fff;position:sticky;bottom:0}select{max-width:100%;min-width:0;flex:1}nav label{display:flex;align-items:center;gap:8px}html{overflow-wrap:anywhere}main{max-width:1280px;padding:0}.slide.fade{animation:entry .25s ease-out}@keyframes entry{from{opacity:0}to{opacity:1}}@media(prefers-reduced-motion:reduce){.slide.fade{animation:none}}@media print{.slide{display:block!important;break-after:page;min-height:0}details{display:none}}'''
js='''const slides=[...document.querySelectorAll('.slide')],sel=document.getElementById('select'),status=document.getElementById('status'),motion=document.getElementById('motion');let index=0;function show(n){index=Math.max(0,Math.min(slides.length-1,n));slides.forEach((s,i)=>{s.hidden=i!==index;s.classList.toggle('fade',i===index&&motion.checked&&!matchMedia('(prefers-reduced-motion: reduce)').matches)});sel.value=index;status.textContent='Slide '+(index+1)+' of '+slides.length;document.getElementById('previous').disabled=index===0;document.getElementById('next').disabled=index===slides.length-1}document.getElementById('previous').onclick=()=>show(index-1);document.getElementById('next').onclick=()=>show(index+1);sel.onchange=()=>show(Number(sel.value));document.addEventListener('keydown',e=>{if(e.target.closest('button,input,select,textarea,summary,a,[contenteditable]'))return;let n;if(e.key==='ArrowRight'||e.key===' '){n=index+1}else if(e.key==='ArrowLeft'){n=index-1}else if(e.key==='Home'){n=0}else if(e.key==='End'){n=slides.length-1}else{return}e.preventDefault();show(n)});show(0);'''
(out/'Teacher-private/Lesson_2_Slides.html').write_text(f'<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Teacher-only Lesson 2 slides</title><style>{css}{slidecss}</style><main>'+''.join(parts)+f'</main><nav aria-label="Slide controls"><button id="previous">Previous</button><button id="next">Next</button><label for="select">Slide</label><select id="select">{options}</select><label><input id="motion" type="checkbox">Fade</label><span id="status" aria-live="polite"></span></nav><script>{js}</script></html>')
